function operationGuides(spec, item, operation, method) {
  const parameter = (value) => value.$ref
    ? spec.components?.parameters?.[value.$ref.split("/").at(-1)] : value
  const parameters = [...(item.parameters ?? []), ...(operation.parameters ?? [])].map(parameter)
  const has = (location, name) => parameters.some((entry) => entry?.in === location && entry.name.toLowerCase() === name.toLowerCase())
  const links = [
    ["Authentication", "/api/authentication"],
    ["Conventions", "/api/conventions"],
  ]
  if (["resolveKnowledgeRepositoryConflict", "importKnowledgeRepository", "syncKnowledgeRepository"].includes(operation.operationId)) links.push(["Follow background work", "/api/operations"])
  if (operation.tags?.includes("Operations")) links.push(["Follow background work", "/api/operations"])
  if (operation.operationId === "bulkUpdateTasks") links.push(["Change several Tasks", "/api/bulk"])
  if (/Webhook/.test(operation.operationId ?? "")) links.push(["Receive Task webhooks", "/api/webhooks"])
  if (["listTaskRichEntities", "beginIntegrationAuthorization", "completeIntegrationAuthorizationWithCredential", "listWorkspaceIntegrationInstallations", "requestIntegrationProvider", "requestIntegrationAction", "getIntegrationAction", "disconnectIntegrationBinding", "verifySentryBinding", "listIntegrationSubscriptions", "createIntegrationSubscription", "listIntegrationCatalog", "disconnectIntegrationInstallation", "getIntegrationInstallation", "listIntegrationActionDefinitions", "getIntegrationInstallationManagement", "listIntegrationResources", "refreshIntegrationResources", "updateIntegrationSubscription", "listPersonalIntegrationIdentities", "disconnectPersonalIntegrationIdentity", "listProjectIntegrationBindings", "createProjectIntegrationBinding"].includes(operation.operationId))
    links.push(["Integrations", "/api/integrations"])
  if (has("query", "cursor")) links.push(["Pagination", "/api/pagination"])
  if (["getMilestone", "updateMilestone", "archiveMilestone"].includes(operation.operationId))
    links.push(["Milestones", "/api/projects#milestones"])
  if (["updateProjectState", "archiveProjectState", "archiveAndReplaceProjectState", "moveProjectState"].includes(operation.operationId))
    links.push(["Project lifecycle states", "/api/projects#lifecycle-states"])
  if (["getWorkspacePersonProfile", "listWorkspacePersonActivity"].includes(operation.operationId))
    links.push(["Conditional reads", "/api/conventions#cache-and-conditional-reads"])
  if (method === "get" && (has("header", "If-None-Match") || has("header", "If-Match") || (["getProjectDisplayPreferences", "getProjectShortcuts"].includes(operation.operationId) && operation.responses?.["304"])))
    links.push(["Conditional reads", "/api/conventions#cache-and-conditional-reads"])
  if (method !== "get" && has("header", "If-Match"))
    links.push(["Conditional edits", "/api/writes#make-an-edit"])
  if (has("header", "Idempotency-Key"))
    links.push(["Recover an unknown outcome", "/api/writes#recover-an-unknown-outcome"])
  links.push(["Errors and recovery", "/api/errors"])
  return links
}

export function operationGuideLinks(operation, markdown = false) {
  const resource = `${referencePath}/${operation.group}#${operation.id}`
  return [...operation.guides, ["Resource reference", resource]].map(([label, link]) => {
    const [path, fragment] = link.split("#")
    return `[${label}](${path}${markdown ? ".md" : ""}${fragment ? `#${fragment}` : ""})`
  }).join(" · ")
}

